import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <math.h>

#define THREADS 256
#define ROWS_PER_BLOCK 4
__inline__ __device__ float warpReduceSum(float val){
    for(int offset=16; offset>0; offset>>=1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}
__global__ void flash_attn_kernel(const half* __restrict__ Q,
                                    const half* __restrict__ K,
                                    const half* __restrict__ V,
                                    half* __restrict__ O,
                                    int B, int H, int S, int D){
    int num_tiles = (S + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    int tileIdx = blockIdx.x;
    int bh = tileIdx / num_tiles;
    int tile = tileIdx % num_tiles;
    int b = bh / H;
    int h = bh % H;
    int row_start = tile * ROWS_PER_BLOCK;
    int rows_in_tile = min(ROWS_PER_BLOCK, S - row_start);
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int per_thread = D / nthreads;
    extern __shared__ float smem[];
    float* q_smem = smem;                         // ROWS_PER_BLOCK * D floats
    float* warp_sums = smem + ROWS_PER_BLOCK*D;    // numWarps floats
    int numWarps = nthreads / 32;
    int lane = tid & 31;
    int wid = tid >> 5;
    size_t base_idx = ((size_t)(b*H+h)*S);
    const half* K_base = K + base_idx*D;
    const half* V_base = V + base_idx*D;
    for(int r=0;r<rows_in_tile;r++){
        const half* Q_ptr = Q + (base_idx + row_start + r)*D;
        float* q_row = q_smem + (size_t)r*D;
        for(int idx = tid; idx < D; idx += nthreads){
            q_row[idx] = __half2float(Q_ptr[idx]);
        }
    }
    __syncthreads();
    float acc[ROWS_PER_BLOCK][8];
    #pragma unroll
    for(int r=0;r<ROWS_PER_BLOCK;r++){
        #pragma unroll
        for(int k=0;k<8;k++) acc[r][k]=0.0f;
    }
    float scale = rsqrtf((float)D);
    __shared__ float s_m[ROWS_PER_BLOCK];
    __shared__ float s_l[ROWS_PER_BLOCK];
    __shared__ float s_factor[ROWS_PER_BLOCK];
    __shared__ float s_expscore[ROWS_PER_BLOCK];
    if(tid==0){
        #pragma unroll
        for(int r=0;r<ROWS_PER_BLOCK;r++){ s_m[r] = -1e30f; s_l[r] = 0.0f; }
    }
    __syncthreads();
    for(int j=0;j<S;j++){
        const half* K_ptr = K_base + (size_t)j*D;
        const float2* K_vec = reinterpret_cast<const float2*>(K_ptr + tid*per_thread);
        float kf[8];
        int kv_iters = per_thread/4;
        #pragma unroll
        for(int k=0;k<kv_iters;k++){
            float2 v2 = K_vec[k];
            half2 k0 = *reinterpret_cast<half2*>(&v2.x);
            half2 k1 = *reinterpret_cast<half2*>(&v2.y);
            float2 kf0 = __half22float2(k0);
            float2 kf1 = __half22float2(k1);
            kf[k*4+0]=kf0.x; kf[k*4+1]=kf0.y; kf[k*4+2]=kf1.x; kf[k*4+3]=kf1.y;
        }
        const half* V_ptr = V_base + (size_t)j*D;
        const float2* V_vec = reinterpret_cast<const float2*>(V_ptr + tid*per_thread);
        float vf[8];
        #pragma unroll
        for(int k=0;k<kv_iters;k++){
            float2 v2 = V_vec[k];
            half2 v0 = *reinterpret_cast<half2*>(&v2.x);
            half2 v1 = *reinterpret_cast<half2*>(&v2.y);
            float2 vf0 = __half22float2(v0);
            float2 vf1 = __half22float2(v1);
            vf[k*4+0]=vf0.x; vf[k*4+1]=vf0.y; vf[k*4+2]=vf1.x; vf[k*4+3]=vf1.y;
        }
        for(int r=0;r<rows_in_tile;r++){
            float* q_row = q_smem + (size_t)r*D;
            float partial = 0.0f;
            #pragma unroll
            for(int k=0;k<per_thread;k++){
                int d = tid*per_thread + k;
                partial += q_row[d]*kf[k];
            }
            partial = warpReduceSum(partial);
            if(lane==0) warp_sums[wid]=partial;
            __syncthreads();
            if(wid==0){
                float v = (lane<numWarps)? warp_sums[lane] : 0.0f;
                v = warpReduceSum(v);
                if(lane==0){
                    float score = v*scale;
                    float m_old = s_m[r];
                    float newmax = fmaxf(m_old, score);
                    float factor = expf(m_old - newmax);
                    float expscore = expf(score - newmax);
                    s_factor[r] = factor;
                    s_expscore[r] = expscore;
                    s_l[r] = s_l[r]*factor + expscore;
                    s_m[r] = newmax;
                }
            }
            __syncthreads();
            float factor = s_factor[r];
            float expscore = s_expscore[r];
            #pragma unroll
            for(int k=0;k<per_thread;k++){
                acc[r][k] = acc[r][k]*factor + expscore*vf[k];
            }
            __syncthreads();
        }
    }
    for(int r=0;r<rows_in_tile;r++){
        float l_final = s_l[r];
        half* O_ptr = O + (base_idx + row_start + r)*D;
        #pragma unroll
        for(int k=0;k<per_thread;k++){
            int d = tid*per_thread + k;
            O_ptr[d] = __float2half(acc[r][k]/l_final);
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V){
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == torch::kHalf, "expected half precision");
    Q = Q.contiguous();
    K = K.contiguous();
    V = V.contiguous();
    auto B = Q.size(0);
    auto H = Q.size(1);
    auto S = Q.size(2);
    auto D = Q.size(3);
    auto O = torch::empty_like(Q);
    int threads = THREADS;
    int num_tiles = (S + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    int blocks = B*H*num_tiles;
    int numWarps = threads/32;
    size_t shmem = (size_t)ROWS_PER_BLOCK*D*sizeof(float) + numWarps*sizeof(float);
    flash_attn_kernel<<<blocks, threads, shmem>>>(
        reinterpret_cast<half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, D
    );
    return O;
}
'''

cpp_source = r'''
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
'''

flash_attn = load_inline(
    name="flash_attn",
    cpp_sources=cpp_source,
    cuda_sources=source,
    functions=["flash_attention_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, Q, K, V):
        return flash_attn.flash_attention_forward(Q, K, V)

