    for(int j=0;j<S;j++){
        const half* K_ptr = K_base + (size_t)j*D;
        float partial = 0.0f;
        const float2* K_vec = reinterpret_cast<const float2*>(K_ptr + tid*per_thread);
        #pragma unroll
        for(int k=0;k<per_thread/4;k++){
            float2 kv = K_vec[k];
            half2 k0 = *reinterpret_cast<half2*>(&kv.x);
            half2 k1 = *reinterpret_cast<half2*>(&kv.y);
            float2 kf0 = __half22float2(k0);
            float2 kf1 = __half22float2(k1);
