        }
        partial = warpReduceSum(partial);
        if(lane==0) warp_sums[wid]=partial;
        __syncthreads();
        if(wid==0){
            float v = (lane<numWarps)? warp_sums[lane] : 0.0f;
            v = warpReduceSum(v);
