        float expscore = s_expscore;
        const half* V_ptr = V_base + (size_t)j*D;
        const float2* V_vec = reinterpret_cast<const float2*>(V_ptr + tid*per_thread);
        #pragma unroll
        for(int k=0;k<per_thread/4;k++){
